import { AnimatePresence, MotionProps, Variants, motion } from 'framer-motion';
import React, { useEffect } from 'react';
import { useIntl } from 'react-intl';
import { isElement } from 'react-is';
import styled from 'styled-components';

import AnimationsJS from '@dynatrace/strato-design-tokens/animations-js';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import { XmarkIcon } from '@dynatrace/strato-icons';

import { _useMicroguideContext } from './hooks/useMicroguideContext.js';
import { Button } from '../../buttons/button/Button.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { Content } from '../shared-components/Content.js';
import { Title } from '../shared-components/Title.js';
import { Visual } from '../shared-components/Visual.js';

//#region Typings
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface MicroguideStepProps extends WithChildren {}

type MicroguideStepSlots = {
  title: React.ReactElement | null;
  visual: React.ReactElement | null;
  content: React.ReactElement | null;
};
//#endregion Typings

//#region StyledComponents
const StepContainer = /* @__PURE__ */ styled(motion(Flex))({
  maxHeight: `calc(100vh - calc(${Spacings.Size32} + ${Spacings.Size56}))`,
  overflow: 'hidden',
});

const TitleWrapper = /* @__PURE__ */ styled(Flex)({
  position: 'relative',
});

const VisualWrapper = /* @__PURE__ */ styled.div({
  position: 'relative',
  margin: `0 ${Spacings.Size16} ${Spacings.Size8}`,
});

const ContentWrapper = /* @__PURE__ */ styled.div({
  position: 'relative',
  overflow: 'hidden',
  display: 'flex',
  flexDirection: 'column',
});

const AnimatedContent = /* @__PURE__ */ styled(motion(Flex))({
  overflow: 'hidden',
  padding: `0 ${Spacings.Size16}`,
});
//#endregion StyledComponents

const contentVariants: Variants = {
  enter: (isNext: boolean) => {
    return {
      x: isNext ? '100%' : '-100%',
      opacity: 0,
    };
  },
  center: {
    x: 0,
    opacity: 1,
    position: 'relative',
  },
  exit: (isNext: boolean) => {
    return {
      x: isNext ? '-100%' : '100%',
      opacity: 0,
      position: 'absolute',
      left: 0,
    };
  },
};

const fadeProps: MotionProps = {
  initial: {
    opacity: 0,
  },
  animate: {
    opacity: 1,
    position: 'relative',
  },
  exit: {
    opacity: 0,
    position: 'absolute',
    left: 0,
  },
  transition: {
    duration: AnimationsJS.SlideIn.Duration.Base,
    ease: AnimationsJS.Move.Easing,
  },
};

/** Container for a single step of the Microguide. */
export const Step = ({ children }: MicroguideStepProps) => {
  const {
    onClose,
    currentStep,
    totalSteps,
    isNext,
    setHasContent,
    setHasTitle,
    closeButtonRef,
    closedOnKeydown,
  } = _useMicroguideContext();
  const intl = useIntl();
  const slots: MicroguideStepSlots = {
    title: null,
    visual: null,
    content: null,
  };

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case Title:
          slots.title = child;
          break;
        case Visual:
          slots.visual = child;
          break;
        case Content:
          slots.content = child;
          break;
        default:
          // eslint-disable-next-line no-console
          console.warn(
            'Only Title, Visual and Content are valid children of Microguide.Step.',
          );
      }
    } else {
      // eslint-disable-next-line no-console
      console.warn('The used child is not supported by Microguide.Step.');
    }
  });

  useEffect(() => {
    setHasTitle(slots.title !== undefined);
    setHasContent(slots.content !== undefined);
  }, [setHasContent, setHasTitle, slots.content, slots.title]);

  return (
    <StepContainer flexDirection="column" gap={8}>
      <Flex
        flexDirection="row"
        justifyContent="space-between"
        alignItems="flex-start"
        gap={16}
        paddingTop={8}
        paddingLeft={16}
        paddingRight={8}
      >
        <TitleWrapper
          flexItem
          paddingY={6}
          flexGrow={1}
          id="strato-microguide-title"
        >
          <AnimatePresence initial={false}>
            {slots.title && (
              <motion.div
                {...fadeProps}
                key={`strato-microguide-title-${currentStep}`}
              >
                {slots.title}
              </motion.div>
            )}
          </AnimatePresence>
        </TitleWrapper>
        <Button
          onClick={() => onClose(currentStep, currentStep + 1 === totalSteps)}
          onKeyDown={() => (closedOnKeydown.current = true)}
          ref={closeButtonRef}
          aria-label={intl.formatMessage({
            defaultMessage: 'Close microguide',
            id: '0yl3EugW5oCHVbO1',
            description: 'Close the microguide.',
          })}
        >
          <Button.Prefix>
            <XmarkIcon />
          </Button.Prefix>
        </Button>
      </Flex>
      {slots.visual && (
        <VisualWrapper>
          <AnimatePresence initial={false}>
            <motion.div
              {...fadeProps}
              key={`strato-microguide-visual-${currentStep}`}
            >
              {slots.visual}
            </motion.div>
          </AnimatePresence>
        </VisualWrapper>
      )}
      {slots.content && (
        <ContentWrapper id="strato-microguide-content">
          <AnimatePresence initial={false} custom={isNext}>
            <AnimatedContent
              variants={contentVariants}
              custom={isNext}
              initial="enter"
              animate="center"
              exit="exit"
              transition={{
                duration: AnimationsJS.SlideIn.Duration.Base,
                ease: AnimationsJS.Move.Easing,
              }}
              key={`strato-microguide-content-${currentStep}`}
              flexDirection="column"
            >
              {slots.content}
            </AnimatedContent>
          </AnimatePresence>
        </ContentWrapper>
      )}
    </StepContainer>
  );
};

Step['displayName'] = 'Microguide.Step';
